#include <omp.h>
#include <vector>
#include <array>
#include <cstddef>

void binsBy10Count(std::vector<double> const& x, std::array<size_t, 10> &bins) {
    bins.fill(0);

    #pragma omp parallel
    {
        std::array<size_t, 10> local{};
        local.fill(0);

        #pragma omp for nowait
        for (std::size_t i = 0; i < x.size(); ++i) {
            double v = x[i];

            // Clamp to valid range [0, 100], then map to bins [0..9]
            if (v < 0.0) v = 0.0;
            if (v > 100.0) v = 100.0;

            std::size_t idx = static_cast<std::size_t>(v / 10.0);
            if (idx >= 10) idx = 9; // ensure v==100 goes to last bin

            local[idx] += 1;
        }

        #pragma omp critical
        {
            for (std::size_t b = 0; b < 10; ++b) {
                bins[b] += local[b];
            }
        }
    }
}
